    <script>function toggle(id){const x=document.getElementById(id);x.type=x.type==='password'?'text':'password'}function strength(value){let score=0;if(value.length>=8)score++;if(value.length>=12)score++;if(/[0-9]/.test(value))score++;if(/[^A-Za-z0-9]/.test(value))score++;for(let i=1;i<=4;i++)document.getElementById('bar'+i).className='h-1.5 flex-1 rounded '+(i<=score?'bg-primary':'bg-slate-200');let text=score>=4?'Strong password':score>=2?'Medium password':'Use 8+ characters';document.getElementById('strength').textContent=text}function nextStep(){let x=document.getElementById('feedback');x.className='mb-5 rounded-xl border border-green-200 bg-green-50 px-4 py-3 text-xs font-semibold text-green-900';x.textContent='Account details saved. Classroom setup is ready for the next step.';x.classList.remove('hidden');setTimeout(()=>{window.location.href='{{ route('teacher.dashboard') }}'},900)}</script>
    <script>
        const registrationForm = document.getElementById('registration');
        const passwordGrid = document.getElementById('password').closest('.grid');
        passwordGrid.insertAdjacentHTML('beforebegin', '<div class="rounded-2xl border border-green-100 bg-green-50 p-4"><p class="mb-3 text-xs font-black uppercase tracking-widest text-primary">Classroom setup</p><div class="grid gap-4 sm:grid-cols-2"><label><span class="mb-2 block text-sm font-bold text-slate-700">Class name *</span><input required name="class_name" value="Grade 8 C++ Programming" class="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-green-700"></label><label><span class="mb-2 block text-sm font-bold text-slate-700">Class code *</span><input name="class_code" placeholder="Leave blank to generate" maxlength="20" class="w-full rounded-xl border border-slate-200 px-4 py-3 font-mono text-sm uppercase outline-none focus:border-green-700"></label><label><span class="mb-2 block text-sm font-bold text-slate-700">Grade *</span><input required name="grade" value="Grade 8" class="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-green-700"></label><label><span class="mb-2 block text-sm font-bold text-slate-700">Period *</span><input required name="period" value="Period 3" class="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-green-700"></label></div><p class="mt-3 text-xs text-slate-500">Students will enter this code during registration.</p></div>');

        async function nextStep() {
            const feedback = document.getElementById('feedback');
            const button = registrationForm.querySelector('button[type="submit"]');
            button.disabled = true;
            button.textContent = 'Creating account…';
            feedback.className = 'mb-5 rounded-xl border border-blue-200 bg-blue-50 px-4 py-3 text-xs font-semibold text-blue-900';
            feedback.textContent = 'Saving your teacher account and classroom…';
            feedback.classList.remove('hidden');

            try {
                const response = await fetch('{{ route('teacher.register.store') }}', {
                    method: 'POST',
                    headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content},
                    body: new FormData(registrationForm),
                });
                const result = await response.json();
                if (!response.ok) throw new Error(result.message || 'Registration failed.');
                feedback.className = 'mb-5 rounded-xl border border-green-200 bg-green-50 px-4 py-3 text-xs font-semibold text-green-900';
                feedback.textContent = 'Account created. Your student join code is ' + result.join_code + '. Opening the Teacher Dashboard…';
                setTimeout(() => window.location.href = '{{ route('teacher.dashboard') }}', 1200);
            } catch (error) {
                feedback.className = 'mb-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-xs font-semibold text-red-800';
                feedback.textContent = error.message;
                button.disabled = false;
                button.textContent = 'Continue to Classroom Setup →';
            }
        }
    </script>
</body>
